package com.tecsup.controller; import com.tecsup.model.Categoria; import com.tecsup.repository.CategoriaRepository; import com.tecsup.dto.CategoriaRequest; import jakarta.validation.Valid; import org.springframework.http.*; import org.springframework.web.bind.annotation.*; import java.util.*; import org.springframework.web.bind.annotation.ExceptionHandler; @RestController @RequestMapping("/api/categorias") public class CategoriaController { private final CategoriaRepository repo; public CategoriaController(CategoriaRepository r){repo=r;} @GetMapping public List<Categoria> all(){return repo.findAll();} @GetMapping("/{id}") public Categoria one(@PathVariable Long id){return repo.findById(id).orElseThrow(()->new NoSuchElementException("Categoria no encontrado: "+id));} @PostMapping public ResponseEntity<Categoria> create(@Valid @RequestBody CategoriaRequest r){Categoria e=new Categoria(); e.setNombre(r.nombre()); e.setEstado(r.estado()); return ResponseEntity.status(HttpStatus.CREATED).body(repo.save(e));} @PutMapping("/{id}") public Categoria update(@PathVariable Long id,@Valid @RequestBody CategoriaRequest r){Categoria e=one(id); e.setNombre(r.nombre()); e.setEstado(r.estado()); return repo.save(e);} @DeleteMapping("/{id}") public ResponseEntity<Void> delete(@PathVariable Long id){repo.delete(one(id));return ResponseEntity.noContent().build();} }

@RestControllerAdvice class ApiErrors { @ExceptionHandler(NoSuchElementException.class) org.springframework.http.ResponseEntity<?> missing(Exception e){return org.springframework.http.ResponseEntity.status(404).body(java.util.Map.of("error",e.getMessage()));} @ExceptionHandler({org.springframework.web.bind.MethodArgumentNotValidException.class,IllegalArgumentException.class}) org.springframework.http.ResponseEntity<?> bad(Exception e){return org.springframework.http.ResponseEntity.badRequest().body(java.util.Map.of("error",e.getMessage()));} }
